package kpt.core.model.config

/**
 * Consent defaults a fresh install starts with — analytics and crash reporting.
 *
 * **SoT: `app-profile/app.yaml#privacy`.** The block below is GENERATED by `./gradlew syncForkConfig`;
 * change the YAML, not this file. Absent = `false`: under GDPR, consent-based processing starts off.
 *
 * These are STARTING values only. `UserData.DEFAULT` reads them for a first run; once the user decides
 * (Settings → Privacy), `core/datastore` persists the choice and that choice wins. Collection is applied
 * from the stored choice at app start (`AppViewModel`), never before it is read.
 */
object AppPrivacyConfig {
    // syncForkConfig:app-privacy:begin — GENERATED from app-profile/app.yaml#privacy. Do not hand-edit.
    /** `privacy.analytics_enabled_by_default` — whether a fresh install shares usage analytics. */
    const val ANALYTICS_ENABLED_BY_DEFAULT: Boolean = false

    /** `privacy.crash_reporting_enabled_by_default` — whether a fresh install sends crash reports. */
    const val CRASH_REPORTING_ENABLED_BY_DEFAULT: Boolean = false

    /** `org.privacy_url` — the privacy policy page, opened in the in-app browser; empty when not set. */
    const val PRIVACY_POLICY_URL: String =
        "https://openmf.github.io/privacy_policy_mifos_mobile.html"
    // syncForkConfig:app-privacy:end
}
